const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Siskiyou County geometry (approximate bounds)
  const siskiyouCounty = ee.Geometry.Polygon([
    [[-123.5, 41.2], [-123.5, 42.0], [-121.5, 42.0], [-121.5, 41.2], [-123.5, 41.2]]
  ]);

  const targetDate = '2021-08-18';
  const dateStart = '2021-08-17';
  const dateEnd = '2021-08-19';

  // 2. Get active fire data from FIRMS (MODIS)
  const fires = ee.FeatureCollection('FIRMS')
    .filter(ee.Filter.date(dateStart, dateEnd))
    .filterBounds(siskiyouCounty);

  const fireCount = fires.size().getInfo();
  print(`Active fires detected: ${fireCount}`);

  if (fireCount === 0) {
    print("No active fires found in the date range.");
    print("<answer>C1</answer>");
    return;
  }

  // 3. Get fire centroids to establish source locations
  const fireCentroid = fires.geometry().centroid();
  const fireCoords = fireCentroid.coordinates().getInfo();
  print(`Fire centroid: [${fireCoords[0].toFixed(3)}, ${fireCoords[1].toFixed(3)}]`);

  // 4. Create region 20 miles north of fires (20 miles ≈ 32 km ≈ 0.29 degrees)
  const northRegion = ee.Geometry.Point(fireCoords)
    .buffer(5000) // 5km buffer
    .translate(0, 32000); // Move 32km north

  // 5. Get Sentinel-2 imagery to detect smoke
  let s2Collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(siskiyouCounty.union(northRegion))
    .filterDate(dateStart, dateEnd)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80));

  let s2Count = s2Collection.size().getInfo();
  print(`Sentinel-2 images found: ${s2Count}`);

  // Fallback to Landsat 8 if no Sentinel-2
  if (s2Count === 0) {
    print("Trying Landsat 8...");
    const l8Collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(siskiyouCounty.union(northRegion))
      .filterDate(dateStart, dateEnd);

    const l8Count = l8Collection.size().getInfo();
    print(`Landsat 8 images found: ${l8Count}`);

    if (l8Count === 0) {
      print("No imagery available.");
      print("<answer>C1</answer>");
      return;
    }

    const l8Image = l8Collection.first();
    const aerosolL8 = l8Image.select('SR_B1'); // Coastal aerosol band

    const aerosolNorth = aerosolL8.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: northRegion,
      scale: 3000,
      maxPixels: 1e9
    }).get('SR_B1');

    const aerosolValue = aerosolNorth.getInfo();
    print(`Aerosol value 20mi north: ${aerosolValue}`);

    if (aerosolValue === null) {
      print("<answer>C3</answer>");
      return;
    }

    // High aerosol values indicate smoke presence
    if (aerosolValue > 8000) {
      print("Smoke detected 20+ miles north of fire source.");
      print("<answer>A</answer>");
    } else {
      print("No significant smoke detected 20+ miles north.");
      print("<answer>B</answer>");
    }
    return;
  }

  // 6. Analyze Sentinel-2 aerosol optical depth
  const s2Image = s2Collection.first();
  const aerosolS2 = s2Image.select('B1'); // Coastal aerosol band

  const aerosolNorthS2 = aerosolS2.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: northRegion,
    scale: 3000,
    maxPixels: 1e9
  }).get('B1');

  const aerosolValueS2 = aerosolNorthS2.getInfo();
  print(`Aerosol value (S2) 20mi north: ${aerosolValueS2}`);

  if (aerosolValueS2 === null) {
    print("<answer>C3</answer>");
    return;
  }

  // Check pixel count
  const pixelCount = aerosolS2.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: northRegion,
    scale: 3000,
    maxPixels: 1e9
  }).get('B1').getInfo();

  print(`Valid pixels: ${pixelCount}`);

  if (pixelCount === 0) {
    print("<answer>C2</answer>");
    return;
  }

  // High aerosol values indicate smoke (typical threshold > 1000 for S2)
  if (aerosolValueS2 > 1000) {
    print("Smoke plume detected 20+ miles north.");
    print("<answer>A</answer>");
  } else {
    print("No smoke plume detected 20+ miles north.");
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
